\underline{\Hilbfunctor}^{d_2}_{X/k}
\longrightarrow
\underline{\Hilbfunctor}^{d_1 + d_2}_{X/k}
$$
which is finite locally free of degree ${d_1 + d_2 \choose d_1}$.
\end{enumerate}

